    use std::borrow::Cow;

    #[test]
    fn compact_byte_error_preserves_all_public_fields_message_ownership_and_zero_backing() {
        for message in [
            Cow::Borrowed(""),
            Cow::Borrowed("borrowed oracle refusal"),
            Cow::Owned("quoted \"text\", NUL\0, LF\n, UTF-8 λ".to_owned()),
        ] {
